(() => {
'use strict';
const $=id=>document.getElementById(id), A=v=>Array.isArray(v)?v:[], C=v=>String(v??'').trim();
const KEY='APLUS_AI_TUTOR_STUDENT_V7';
let state; try{state=JSON.parse(localStorage.getItem(KEY))}catch(e){}
state=state||{version:7,level:'P3',questions:0,correct:0,skills:{},mistakes:[],history:[]};
const old=(()=>{try{return JSON.parse(localStorage.getItem('APLUS_AI_TUTOR_STUDENT_V6'))}catch(e){return null}})();
if(old&&state.questions===0){state={...state,...old,version:7};save()}
function save(){localStorage.setItem(KEY,JSON.stringify(state))}
function shuffle(a){return [...a].sort(()=>Math.random()-.5)}
function esc(s){return C(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
const R={P3:1,P4:2,P5:3,P6:4};
function rank(r){let n=C(r.level).toUpperCase();return n.includes('P6')?4:n.includes('P5')?3:n.includes('P4')?2:1}
function skill(name){return state.skills[name]||{correct:0,total:0,mastery:0}}
function mark(name,ok){let s=skill(name);s.total++;if(ok)s.correct++;s.mastery=Math.round(s.correct/s.total*100);s.lastWrong=ok?s.lastWrong:Date.now();state.skills[name]=s}
const vocabDB=()=>A(window.vocabulary); // P6 source: data/vocabulary.js ONLY
const grammarDB=()=>typeof APLUS_AI_DB_V1_GRAMMAR_LARGE_P3P5_BATCH01!=='undefined'?A(APLUS_AI_DB_V1_GRAMMAR_LARGE_P3P5_BATCH01):[];
const richDB=()=>[typeof APLUS_AI_DB_V1_VOCABULARY_RICH_P3!=='undefined'?APLUS_AI_DB_V1_VOCABULARY_RICH_P3:[],typeof APLUS_AI_DB_V1_VOCABULARY_RICH_P45!=='undefined'?APLUS_AI_DB_V1_VOCABULARY_RICH_P45:[]].flat();
function p6Question(r){
  const word=C(r.word), meaning=C(r.meaning), ex=C(r.example); if(!word||!meaning||!ex)return null;
  const idx=ex.toLowerCase().indexOf(word.toLowerCase());
  if(idx<0)return null;
  const shown=ex.slice(0,idx)+'_____'+ex.slice(idx+word.length);
  const pool=vocabDB().filter(x=>x!==r && C(x.partOfSpeech).toLowerCase()===C(r.partOfSpeech).toLowerCase() && C(x.word).toLowerCase()!==word.toLowerCase());
  let ds=shuffle(pool).map(x=>C(x.word)).filter(Boolean).slice(0,3);
  if(ds.length<3)ds=shuffle(vocabDB().filter(x=>C(x.word).toLowerCase()!==word.toLowerCase())).map(x=>C(x.word)).filter(Boolean).slice(0,3);
  if(ds.length<3)return null;
  return {id:'p6-vocab:'+r.id,skill:'P6 Vocabulary',topic:word,prompt:shown,answer:word,options:shuffle([word,...ds]),explain:'Meaning: '+meaning+(r.synonyms?.length?' Synonym: '+r.synonyms[0]+'.':''),source:'data/vocabulary.js',difficulty:Number(r.level)||6};
}
function p6Questions(){
  const records=shuffle(vocabDB()); const out=[]; for(const r of records){const q=p6Question(r);if(q)out.push(q);if(out.length>=30)break} return out;
}
const G={
'subject-verb agreement':['The box of pencils _____ on the table.',['is','are','be','am'],'is'],
'present simple':['Every morning, Amir _____ to school.',['walks','walk','walking','walked'],'walks'],
'present continuous':['Look! The children _____ football.',['are playing','play','played','have played'],'are playing'],
'past simple':['Yesterday, we _____ to the museum.',['went','go','gone','going'],'went'],
'present perfect':['She has _____ her project already.',['finished','finish','finishing','finishes'],'finished'],
'modal verbs':['You _____ wear your seat belt.',['must','must to','musts','must wearing'],'must'],
'adverbs':['The girl sang _____.',['beautifully','beautiful','beauty','beautify'],'beautifully'],
'relative clauses':['The boy _____ won the race is my friend.',['who','which','where','what'],'who'],
'conditional sentences':['If it _____, we will stay indoors.',['rains','will rain','rained','raining'],'rains'],
'gerunds and infinitives':['I enjoy _____ storybooks.',['reading','to read','read','reads'],'reading'],
'object pronouns':['Mum gave the book to _____.',['me','I','my','mine'],'me'],
'negative sentences':['She does not _____ coffee.',['drink','drinks','drank','drinking'],'drink'],
'passive':['English _____ in many countries.',['is spoken','is speak','speaks','is speaking'],'is spoken'],
'infinitive of purpose':['I went to the library _____ a book.',['to borrow','for borrow','borrowing','borrowed'],'to borrow'],
'comparative adjectives':['My bag is _____ than yours.',['heavier','heaviest','heavy','more heavy'],'heavier'],
'superlative adjectives':['Ali is the _____ runner in the class.',['fastest','faster','most fast','fast'],'fastest'],
'as as':['The new bag is as _____ as the old one.',['heavy','heavier','heaviest','more heavy'],'heavy']
};
function grammar(){const out=[];for(const r of grammarDB()){const text=(C(r.topic)+' '+C(r.focus)+' '+A(r.skills).join(' ')).toLowerCase();const k=Object.keys(G).find(x=>text.includes(x));if(!k)continue;const g=G[k];if(out.some(q=>q.prompt===g[0]))continue;out.push({id:'g:'+r.id,skill:'Grammar',topic:r.topic,prompt:g[0],options:shuffle(g[1]),answer:g[2],explain:C(A(r.rules)[0])||'Choose the form that fits the sentence.',source:'Grammar Database',difficulty:Number(r.difficulty)||2});if(out.length>=30)break}return shuffle(out)}
function p3p5Vocab(){const out=[];for(const r of shuffle(richDB())){const ex=C(A(r.examples)[0]),word=C(r.word);if(!ex||!word)continue;const re=new RegExp('\\b'+word.replace(/[.*+?^${}()|[\\]\\]/g,'\\$&')+'(?:s|ed|ing)?\\b','i'),m=ex.match(re);if(!m)continue;const ans=m[0],prompt=ex.replace(re,'_____');const ds=shuffle(richDB().filter(x=>C(x.word).toLowerCase()!==word.toLowerCase()&&C(x.word))).slice(0,3).map(x=>C(x.word));if(ds.length<3)continue;out.push({id:'v:'+r.id,skill:'Vocabulary',topic:word,prompt,answer:ans,options:shuffle([ans,...ds]),explain:'Meaning: '+C(r.definition),source:'P3–P5 Vocabulary Database',difficulty:Number(r.difficulty)||2});if(out.length>=30)break}return out}
function build(mode){let all;if(state.level==='P6')all=p6Questions();else if(mode==='grammar')all=grammar();else if(mode==='vocabulary')all=p3p5Vocab();else if(mode==='review'){const ids=new Set(state.mistakes.map(x=>x.id));all=[...p3p5Vocab(),...grammar(),...(state.level==='P6'?p6Questions():[])].filter(q=>ids.has(q.id));if(!all.length)all=state.level==='P6'?p6Questions():shuffle([...p3p5Vocab(),...grammar()])}else all=shuffle([...p3p5Vocab(),...grammar()]);session={list:all.slice(0,10),index:0,correct:0,wrong:0,mode};render()}
let session={list:[],index:0,correct:0,wrong:0,mode:''};
function finish(){const t=session.correct+session.wrong,p=t?Math.round(session.correct/t*100):0;let h,b;if(!t){h='No practice completed';b='No question was answered. Choose a practice mode to begin.'}else if(p===100){h='Excellent accuracy';b='You answered every question correctly. The next session can introduce a higher challenge.'}else if(p>=80){h='Strong progress';b='You answered '+session.correct+' of '+t+' questions correctly. Review the few mistakes before moving on.'}else if(p>=50){h='More practice needed';b='You answered '+session.correct+' of '+t+' questions correctly. Let’s revisit the skills that need more practice.'}else{h='Let’s rebuild the basics';b='You answered '+session.correct+' of '+t+' questions correctly. We will slow down, explain the key idea, and practise it step by step.'}$('quizLabel').textContent='SESSION COMPLETE';$('questionProgress').textContent='Tutor Brain updated';$('questionArea').innerHTML='<div class="empty-quiz"><div class="empty-icon">'+(p>=80?'✓':'↻')+'</div><h3>'+h+'</h3><p>'+b+'</p><p><strong>Session result: '+session.correct+'/'+t+' correct · '+p+'%</strong></p><p>'+(p<50?'Your next session will prioritise recovery practice.':'Your next session will adapt to your recent answers.')+'</p></div>';update()}
function render(){const q=session.list[session.index];if(!q)return finish();$('quizLabel').textContent=q.skill.toUpperCase();$('questionProgress').textContent='Question '+(session.index+1)+' of '+session.list.length+' · '+state.level;$('questionArea').innerHTML='<div class="question-text">'+esc(q.prompt)+'</div><div class="options">'+q.options.map((o,i)=>'<button class="option-btn" type="button" data-answer="'+esc(o)+'"><b>'+String.fromCharCode(65+i)+'.</b> '+esc(o)+'</button>').join('')+'</div><div id="feedbackSlot"></div>';$('questionArea').querySelectorAll('.option-btn').forEach(b=>b.onclick=()=>answer(q,b))}
function answer(q,b){if(b.disabled)return;const chosen=C(b.dataset.answer),ok=chosen.toLowerCase()===C(q.answer).toLowerCase();$('questionArea').querySelectorAll('.option-btn').forEach(x=>{x.disabled=true;if(C(x.dataset.answer).toLowerCase()===C(q.answer).toLowerCase())x.classList.add('correct')});if(!ok)b.classList.add('wrong');state.questions++;if(ok){state.correct++;session.correct++;state.mistakes=state.mistakes.filter(x=>x.id!==q.id)}else{session.wrong++;state.mistakes.unshift({id:q.id,skill:q.skill,topic:q.topic,answer:q.answer,at:Date.now()});state.mistakes=state.mistakes.slice(0,50)}mark(q.skill,ok);state.history.unshift({id:q.id,ok,skill:q.skill,at:Date.now()});save();const text=ok?'Correct. The answer fits the sentence.':'Not correct yet. The answer is “'+q.answer+'”. Read the sentence again and look for the meaning or grammar clue.';$('feedbackSlot').innerHTML='<div class="feedback '+(ok?'feedback-good':'feedback-fix')+'"><b>'+(ok?'Correct!':'Let’s learn from this.')+'</b><br>'+esc(text)+'<br><small>'+esc(q.explain)+'</small></div><div class="feedback-actions"><button class="next-btn" id="nextQuestion" type="button">'+(session.index+1===session.list.length?'See session result':'Next question')+' →</button></div>';$('nextQuestion').onclick=()=>{session.index++;render()};update()}
function update(){const q=state.questions;$('statQuestions').textContent=q;$('statAccuracy').textContent=q?Math.round(state.correct/q*100)+'%':'—';const a=Object.values(state.skills);$('statMastery').textContent=a.length?Math.round(a.reduce((n,s)=>n+s.mastery,0)/a.length)+'%':'0%';$('statReview').textContent=state.mistakes.length;$('dataStatus').textContent='Tutor Brain V7 ready · '+state.level;$('coachMessage').textContent=state.level==='P6'?'P6 uses the PSLE vocabulary database directly.':'Your answers are shaping the next practice.';const names=state.level==='P6'?['P6 Vocabulary']:['Grammar','Vocabulary'];$('skillsList').innerHTML=names.map(n=>{const s=skill(n);return '<div class="skill-row"><div class="skill-head"><span>'+n+'</span><span>'+s.mastery+'%</span></div><div class="bar"><span style="width:'+s.mastery+'%"></span></div></div>'}).join('');$('reviewList').innerHTML=state.mistakes.length?state.mistakes.slice(0,3).map(m=>'<div class="review-item"><span class="dot"></span><div><b>'+esc(m.skill)+'</b><small>'+esc(m.topic||'Review needed')+'</small></div></div>').join(''):'<div class="review-item"><span class="dot"></span><div><b>No review items yet.</b><small>Complete practice to build your review list.</small></div></div>';$('pathList').innerHTML=state.level==='P6'?'<div class="path-item"><span class="dot"></span><div><b>1. PSLE Vocabulary</b><small>Build meaning and context accuracy from the P6 vocabulary source.</small></div></div><div class="path-item"><span class="dot"></span><div><b>2. Review</b><small>Revisit words you found difficult.</small></div></div><div class="path-item"><span class="dot"></span><div><b>3. Transfer</b><small>Use familiar words in new contexts.</small></div></div>':'<div class="path-item"><span class="dot"></span><div><b>1. Understand</b><small>Read the sentence and identify the clue.</small></div></div><div class="path-item"><span class="dot"></span><div><b>2. Practise</b><small>Strengthen the skill that needs attention.</small></div></div><div class="path-item"><span class="dot"></span><div><b>3. Transfer</b><small>Use the skill in a new context.</small></div></div>'}
document.querySelectorAll('.level-btn').forEach(b=>b.onclick=()=>{state.level=b.dataset.level;document.querySelectorAll('.level-btn').forEach(x=>x.classList.toggle('active',x===b));save();update()});document.querySelectorAll('.practice-card').forEach(b=>b.onclick=()=>{build(b.dataset.mode);$('quizCard').scrollIntoView({behavior:'smooth',block:'start'})});$('closeQuiz').onclick=()=>{$('questionArea').innerHTML='<div class="empty-quiz"><div class="empty-icon">✦</div><h3>Your next question is waiting.</h3><p>Choose a practice mode above.</p></div>'};document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{const a=b.dataset.action;if(a==='challenge')build('mixed');else if(a==='easier')build('review');else if(a==='another')build(state.level==='P6'?'vocabulary':'vocabulary');else if(a==='explain'){const m=state.mistakes[0];$('questionArea').innerHTML=m?'<div class="feedback"><b>Let’s review this mistake</b><br>'+esc(m.topic||m.skill)+'<br><small>Expected answer: '+esc(m.answer)+'</small></div>':'<div class="feedback"><b>No mistake has been recorded yet.</b><br>Complete a question first.</div>'}});$('resetBtn').onclick=()=>{localStorage.removeItem(KEY);location.reload()};update();
})();
